<div class="snippet-code">
<pre class="snippet-code-css lang-css prettyprint-override"><code>body {
  margin: 0;
  display: flex;
  justify-content: flex-end;
}

.container {
  display: flex;
  flex-direction: column;
  flex-wrap: flex;
  gap: 0.5em;
  width: 650px;
  padding: 0.5em;
  z-index: 999;
}

.row {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 0.5em;
}

.col {
  display: flex;
  flex: 1;
  flex-direction: column;
  flex-wrap: wrap;
  gap: 0.5em;
  border: 1px solid #000;
  min-width: 208.333px;
}

.col-mid {
  display: flex;
  flex: 2;
  flex-direction: column;
  flex-wrap: wrap;
  gap: 0.5em;
}

.col-big {
  display: flex;
  flex: 3;
  flex-direction: column;
  flex-wrap: wrap;
  gap: 0.5em;
}

@media only screen and (max-width: 625px) {
  body {
    margin: 0;
  }

  .container {
    max-width: 650px;
    margin: 0px auto !important;
  }

  .col {
    display: flex;
    flex: 1;
    flex-direction: column;
    flex-wrap: wrap;
    gap: 0.5em;
    border: 1px solid #000;
    min-width: 0;
  }

  .row {
    display: flex;
    flex-direction: column;
    flex-wrap: nowrap;
    gap: 0.5em;
